SELECT URLHash, make_date(EventDate) AS EventDate, COUNT(*) AS PageViews FROM hits WHERE CounterID = 62 AND make_date(EventDate) >= '2013-07-01' AND make_date(EventDate) <= '2013-07-31' AND IsRefresh = 0 AND TraficSourceID IN (-1, 6) AND RefererHash = 3594120000172545465 GROUP BY URLHash, make_date(EventDate) ORDER BY PageViews DESC LIMIT 10 OFFSET 100;
